//! Maintained parser/codec and standard split only; fixed malformed fixtures are not a protocol implementation.
use futures_util::{SinkExt,StreamExt};
use tokio::{io::{AsyncReadExt,AsyncWriteExt},net::TcpListener,sync::{Notify,Semaphore,watch}};
use tokio_tungstenite::{WebSocketStream,tungstenite::{Message,Error,protocol::{Role,WebSocketConfig}}};
use std::{sync::{Arc,atomic::{AtomicUsize,Ordering}},time::Duration,future::Future,task::Poll};
fn classify(error:Error)->&'static str{match error{Error::Protocol(_)=>"protocol",Error::Utf8(_)=>"utf8",Error::Capacity(_)=>"capacity",Error::WriteBufferFull(_)=>"write-buffer-full",_=>"other"}}
pub(super) async fn controls(){
 let defaults=WebSocketConfig::default();println!("{}",serde_json::json!({"id":"ws-defaults","read":defaults.read_buffer_size,"write":defaults.write_buffer_size,"max_write":defaults.max_write_buffer_size.to_string(),"message":defaults.max_message_size,"frame":defaults.max_frame_size,"unmasked":defaults.accept_unmasked_frames}));
 for(kind,message)in[("text",Message::Text("é\n🦀".into())),("binary",Message::Binary(vec![0,255,1,128].into()))]{let(a,b)=tokio::io::duplex(1024);let mut client=WebSocketStream::from_raw_socket(a,Role::Client,None).await;let mut server=WebSocketStream::from_raw_socket(b,Role::Server,None).await;client.send(message.clone()).await.unwrap();let observed=server.next().await.unwrap().unwrap();assert_eq!(observed,message);server.send(observed).await.unwrap();assert_eq!(client.next().await.unwrap().unwrap(),message);println!("{}",serde_json::json!({"id":format!("ws-{kind}"),"bytes":message.into_data().to_vec()}));}
 // Read then continue driving the backend, so automatic pong is actually flushed.
 let(a,b)=tokio::io::duplex(1024);let mut client=WebSocketStream::from_raw_socket(a,Role::Client,None).await;let mut server=WebSocketStream::from_raw_socket(b,Role::Server,None).await;client.send(Message::Ping(vec![7,8].into())).await.unwrap();assert!(matches!(server.next().await.unwrap().unwrap(),Message::Ping(_)));server.flush().await.unwrap();let pong=client.next().await.unwrap().unwrap();assert!(matches!(pong,Message::Pong(_)));println!("{}",serde_json::json!({"id":"ws-auto-pong","bytes":pong.into_data().to_vec()}));
 let(a,b)=tokio::io::duplex(1024);let client=WebSocketStream::from_raw_socket(a,Role::Client,None).await;let mut server=WebSocketStream::from_raw_socket(b,Role::Server,None).await;let(mut write,mut read)=client.split();let receive=read.next();tokio::pin!(receive);let pending=std::future::poll_fn(|cx|Poll::Ready(receive.as_mut().poll(cx).is_pending())).await;write.send(Message::Text("duplex".into())).await.unwrap();let observed=server.next().await.unwrap().unwrap();server.send(observed).await.unwrap();assert_eq!(receive.await.unwrap().unwrap().into_text().unwrap().as_str(),"duplex");println!("{}",serde_json::json!({"id":"ws-owned-split","receive_was_pending":pending,"sent_while_pending":true}));
 let(a,b)=tokio::io::duplex(1024);let mut client=WebSocketStream::from_raw_socket(a,Role::Client,None).await;let mut server=WebSocketStream::from_raw_socket(b,Role::Server,None).await;client.send(Message::Close(Some(tokio_tungstenite::tungstenite::protocol::CloseFrame{code:tokio_tungstenite::tungstenite::protocol::frame::coding::CloseCode::Normal,reason:"byeé".into()}))).await.unwrap();let Message::Close(Some(frame))=server.next().await.unwrap().unwrap()else{panic!("close frame")};assert_eq!(u16::from(frame.code),1000);assert_eq!(frame.reason.as_str(),"byeé");let _=server.flush().await;drop(server);while let Some(message)=client.next().await{message.unwrap();}println!("{}",serde_json::json!({"id":"ws-close-frame","code":1000,"reason":"byeé","settled":true}));
 let(a,mut peer)=tokio::io::duplex(1024);let socket=WebSocketStream::from_raw_socket(a,Role::Server,None).await;let(write,read)=socket.split();drop(write);let mut byte=[0u8;1];assert!(tokio::time::timeout(Duration::from_millis(10),peer.read(&mut byte)).await.is_err());drop(read);assert_eq!(peer.read(&mut byte).await.unwrap(),0);println!("{}",serde_json::json!({"id":"ws-half-drop","retained_by_read":true,"eof_after_both":true}));
 let(a,mut peer)=tokio::io::duplex(1024);let socket=WebSocketStream::from_raw_socket(a,Role::Server,None).await;let(mut write,mut read)=socket.split();let(ready,wait)=tokio::sync::oneshot::channel();let task=tokio::spawn(async move{let receive=read.next();tokio::pin!(receive);let pending=std::future::poll_fn(|cx|Poll::Ready(receive.as_mut().poll(cx).is_pending())).await;let _=ready.send(pending);receive.await});assert!(wait.await.unwrap());task.abort();assert!(task.await.unwrap_err().is_cancelled());write.send(Message::Text("retained".into())).await.unwrap();drop(write);let mut observed=Vec::new();peer.read_to_end(&mut observed).await.unwrap();assert_eq!(observed,[vec![0x81,8],b"retained".to_vec()].concat());println!("{}",serde_json::json!({"id":"ws-cancel-read","task_settled":true,"writer_survived":true,"wire_bytes":observed.len()}));
 let malformed=[("invalid-close",vec![0x88,0x82,0,0,0,0,3,231],WebSocketConfig::default()),("unmasked",vec![0x81,1,b'x'],WebSocketConfig::default()),("invalid-utf8",vec![0x81,0x81,0,0,0,0,255],WebSocketConfig::default()),("frame-limit",{let mut frame=vec![0x82,0x91,0,0,0,0];frame.extend([0;17]);frame},WebSocketConfig::default().max_frame_size(Some(16))),("message-limit",{let mut frame=vec![0x82,0xa1,0,0,0,0];frame.extend([0;33]);frame},WebSocketConfig::default().max_message_size(Some(32)))];
 for(id,input,config)in malformed{let(mut peer,wire)=tokio::io::duplex(1024);peer.write_all(&input).await.unwrap();drop(peer);let mut socket=WebSocketStream::from_raw_socket(wire,Role::Server,Some(config)).await;let observed=socket.next().await.unwrap();if id=="invalid-close"{let Message::Close(Some(frame))=observed.unwrap()else{panic!("invalid close must produce backend protocol close")};assert_eq!(u16::from(frame.code),1002);assert_eq!(frame.reason.as_str(),"Protocol violation");println!("{}",serde_json::json!({"id":"ws-invalid-close","observed":"close","code":1002,"reason":frame.reason.as_str()}));}else{let error=observed.unwrap_err();println!("{}",serde_json::json!({"id":format!("ws-{id}"),"error":classify(error)}));}}
 let(a,mut peer)=tokio::io::duplex(1);let socket=WebSocketStream::from_raw_socket(a,Role::Server,None).await;let(mut write,read)=socket.split();let(pending,drain)={let send=write.send(Message::Binary(vec![5;256].into()));tokio::pin!(send);let pending=std::future::poll_fn(|cx|Poll::Ready(send.as_mut().poll(cx).is_pending())).await;let drain=tokio::spawn(async move{let mut bytes=Vec::new();peer.read_to_end(&mut bytes).await.unwrap();bytes});send.await.unwrap();(pending,drain)};drop(write);drop(read);let wire=drain.await.unwrap();println!("{}",serde_json::json!({"id":"ws-backpressure","was_pending":pending,"wire_bytes":wire.len(),"settled":true}));
 // Cancel an actually Pending send, join its owner, then release the retained half.
 let(a,mut peer)=tokio::io::duplex(1);let socket=WebSocketStream::from_raw_socket(a,Role::Server,None).await;let(mut write,read)=socket.split();let(ready,blocked)=tokio::sync::oneshot::channel();let task=tokio::spawn(async move{let send=write.send(Message::Binary(vec![9;256].into()));tokio::pin!(send);assert!(std::future::poll_fn(|cx|Poll::Ready(send.as_mut().poll(cx).is_pending())).await);ready.send(()).unwrap();send.await});blocked.await.unwrap();task.abort();assert!(task.await.unwrap_err().is_cancelled());drop(read);let mut partial=Vec::new();tokio::time::timeout(Duration::from_secs(1),peer.read_to_end(&mut partial)).await.unwrap().unwrap();assert!(partial.len()<260);println!("{}",serde_json::json!({"id":"ws-cancel-send","task_settled":true,"eof_after_both":true}));
 let(a,b)=tokio::io::duplex(1024);let mut client=WebSocketStream::from_raw_socket(a,Role::Client,None).await;let mut server=WebSocketStream::from_raw_socket(b,Role::Server,None).await;let left=async move{client.close(None).await.unwrap();while let Some(value)=client.next().await{value.unwrap();}};let right=async move{server.close(None).await.unwrap();while let Some(value)=server.next().await{value.unwrap();}};tokio::time::timeout(Duration::from_secs(1),async{tokio::join!(left,right);}).await.unwrap();println!("{}",serde_json::json!({"id":"ws-close-race","settled":true}));
}
#[derive(Clone)]struct State{permits:Arc<Semaphore>,active:Arc<AtomicUsize>,changed:Arc<Notify>,stop:watch::Receiver<bool>,grace:Duration}
struct Session{permit:Option<tokio::sync::OwnedSemaphorePermit>,active:Arc<AtomicUsize>,changed:Arc<Notify>}
impl Drop for Session{fn drop(&mut self){drop(self.permit.take());self.active.fetch_sub(1,Ordering::SeqCst);self.changed.notify_waiters();}}
pub(super) async fn serve(){
 use axum::{Router,extract::{State as Extract,WebSocketUpgrade},http::{HeaderMap,StatusCode},response::IntoResponse,routing::get};
 let grace_ms: u64=std::env::args().nth(2).expect("serve requires explicit shutdown grace milliseconds").parse().unwrap();assert!(grace_ms>0);let(tx,rx)=watch::channel(false);let state=State{permits:Arc::new(Semaphore::new(16)),active:Arc::new(AtomicUsize::new(0)),changed:Arc::new(Notify::new()),stop:rx,grace:Duration::from_millis(grace_ms)};
 let route=|Extract(state):Extract<State>,headers:HeaderMap,upgrade:WebSocketUpgrade|async move{
  // Fixture-supplied application hook executes before upgrade; not a facade auth default.
  if headers.get("authorization").and_then(|v|v.to_str().ok())!=Some("Bearer admission"){return StatusCode::UNAUTHORIZED.into_response();}
  if headers.get("origin").and_then(|v|v.to_str().ok())!=Some("https://allowed.invalid"){return StatusCode::FORBIDDEN.into_response();}
  let Ok(permit)=state.permits.clone().try_acquire_owned()else{return StatusCode::SERVICE_UNAVAILABLE.into_response();};state.active.fetch_add(1,Ordering::SeqCst);let session=Session{permit:Some(permit),active:state.active.clone(),changed:state.changed.clone()};
  upgrade.on_upgrade(move|socket|async move{let _session=session;let mut socket=socket;let mut stop=state.stop;let cancelled=tokio::select!{_ = stop.changed()=>true,_ = async{loop{match socket.recv().await{Some(Ok(axum::extract::ws::Message::Text(text))) if text.as_str()=="admission-pending-send"=>{let mut observed=false;for _ in 0..4096{let send=socket.send(axum::extract::ws::Message::Binary(vec![3;131072].into()));tokio::pin!(send);let completed=std::future::poll_fn(|cx|Poll::Ready(match send.as_mut().poll(cx){Poll::Pending=>None,Poll::Ready(result)=>Some(result)})).await;if let Some(result)=completed{result.unwrap();}else{observed=true;println!("{}",serde_json::json!({"pending_send":true,"active":state.active.load(Ordering::SeqCst)}));let _=send.await;break;}}assert!(observed,"explicit stalled-reader fixture never blocked");},Some(Ok(axum::extract::ws::Message::Text(text)))=>if socket.send(axum::extract::ws::Message::Text(text)).await.is_err(){break;},Some(Ok(axum::extract::ws::Message::Binary(bytes)))=>if socket.send(axum::extract::ws::Message::Binary(bytes)).await.is_err(){break;},Some(Ok(axum::extract::ws::Message::Close(_)))=>{let _=socket.flush().await;break;},Some(Ok(_))=>{},_=>break}}}=>false};if cancelled{let _=tokio::time::timeout(state.grace,async{let _=socket.send(axum::extract::ws::Message::Close(None)).await;while socket.recv().await.is_some(){}}).await;}}).into_response()
 };
 let app=Router::new().route("/sse",get(||async{use axum::response::sse::{Sse,Event};Sse::new(futures_util::stream::iter((0..6).map(|i|Ok::<_,std::convert::Infallible>(Event::default().data(format!("chunk {i}"))))))})).route("/ws",get(route)).with_state(state.clone());let listener=TcpListener::bind("127.0.0.1:0").await.unwrap();println!("{}",serde_json::json!({"ready":format!("ws://{}/ws",listener.local_addr().unwrap())}));
 let shutdown=async move{tokio::signal::ctrl_c().await.unwrap();let _=tx.send(true);};axum::serve(listener,app).with_graceful_shutdown(shutdown).await.unwrap();loop{let changed=state.changed.notified();if state.active.load(Ordering::SeqCst)==0{break;}changed.await;}println!("{}",serde_json::json!({"settled":true,"active":0}));
}

#[cfg(feature="websocket-rustls")]pub(super) async fn tls_client(url:&str,ca:Option<&str>){
 use tokio_tungstenite::{Connector,tungstenite::client::IntoClientRequest};
 let connector=ca.map(|path|{use tokio_rustls::rustls::{self,pki_types::{CertificateDer,pem::PemObject}};let pem=std::fs::read(path).unwrap();let mut roots=rustls::RootCertStore::empty();for certificate in CertificateDer::pem_slice_iter(&pem){roots.add(certificate.unwrap()).unwrap();}Connector::Rustls(Arc::new(rustls::ClientConfig::builder().with_root_certificates(roots).with_no_client_auth()))});
 let mut request=url.into_client_request().unwrap();request.headers_mut().insert("authorization","Bearer admission".parse().unwrap());request.headers_mut().insert("origin","https://allowed.invalid".parse().unwrap());
 match tokio_tungstenite::connect_async_tls_with_config(request,None,false,connector).await{Ok((mut socket,_))=>{socket.send(Message::Text("tls".into())).await.unwrap();assert_eq!(socket.next().await.unwrap().unwrap().into_text().unwrap().as_str(),"tls");socket.close(None).await.unwrap();println!("{}",serde_json::json!({"id":"ws-tls-client","connected":true}));},Err(error)=>{println!("{}",serde_json::json!({"id":"ws-tls-client","connected":false,"error":error.to_string()}));}}
}
